SELECT p.id AS position_id, s.id, s.interval_code, s.decision, s.signal_mode, s.candle_open_time, s.generated_at, s.latest_price, s.total_score, s.confidence_score, s.final_entry_allowed, s.primary_blocking_stage FROM crypto_ai.paper_position p JOIN crypto_ai.trade_signal s ON s.symbol = p.symbol AND s.interval_code IN ('1m','5m','1h') AND s.generated_at BETWEEN p.opened_at - INTERVAL 15 MINUTE AND p.closed_at + INTERVAL 2 MINUTE WHERE p.id IN (182,172,162,158,143,137) ORDER BY p.id, s.generated_at LIMIT 1000;